import { test } from 'node:test';
import assert from 'node:assert/strict';
import { saudar, somarTodos, juntarNomes } from './solution.mjs';

test('default é usado quando o segundo argumento não vem', () => {
  assert.equal(saudar('Ana'), 'Olá, Ana!');
});

test('default é ignorado quando o segundo argumento vem', () => {
  assert.equal(saudar('Ana', 'Bom dia'), 'Bom dia, Ana!');
});

test('rest soma qualquer quantidade de números', () => {
  assert.equal(somarTodos(1, 2, 3), 6);
  assert.equal(somarTodos(5), 5);
  assert.equal(somarTodos(), 0);
});

test('rest captura os nomes depois do separador', () => {
  assert.equal(juntarNomes(' | ', 'Ana', 'Bia', 'Cauê'), 'Ana | Bia | Cauê');
  assert.equal(juntarNomes('! ', 'Ana', 'Bia'), 'Ana! Bia');
});

solutionCode:
export function saudar(nome, saudacao = 'Olá') {
  return `${saudacao}, ${nome}!`;
}

export function somarTodos(...numeros) {
  let total = 0;
  for (const n of numeros) {
    total += n;
  }
  return total;
}

export function juntarNomes(separador = ', ', ...nomes) {
  return nomes.join(separador);
}
